import axios from 'axios';

async function downloadUserImages(username: string, apiKey: string) {
  const baseUrl = 'https://api.civitai.com/v1/';
  const images: string[] = [];

  try {
    const response = await axios.get(`${baseUrl}images?created_by=${username}`, {
      headers: {
        'Authorization': `Bearer ${apiKey}`
      }
    });

    if (response.data.length === 0) {
      console.log('No images found for user:', username);
      return;
    }

    for (const image of response.data) {
      const imageUrl = image.url;
      const imageName = image.name;

      const imageResponse = await axios.get(imageUrl, { responseType: 'stream' });
      const imageFile = imageResponse.data.pipe(require('fs').createWriteStream(`${imageName}`));

      images.push(imageName);
      console.log(`Downloaded image: ${imageName}`);
    }

    console.log('All images downloaded successfully.');
  } catch (error) {
    console.error('Error downloading images:', error);
  }

  return images;
}

// Usage:
// Call the function with the desired username and API key
downloadUserImages('deniskropp', '0be1d17f909493be1aa3b7f9224728f2');
```

